INSERT INTO public.countries (id, name, slug, code, short_description, description, image_url, banner_url, is_published, sort_order, education_system, degree_levels, popular_majors, average_tuition, average_living_cost, visa_requirements, official_visa_url)
VALUES 
('11111111-1111-1111-1111-111111111101', 'Du học Mỹ', 'my', 'US', 'Nền giáo dục tinh hoa với hơn 4.000 trường đại học hàng đầu và vô số cơ hội học bổng giá trị cao.', 'Mỹ luôn là điểm đến du học mơ ước của hàng triệu sinh viên toàn cầu. Với nền kinh tế số 1 thế giới và các trường đại học danh tiếng thuộc khối Ivy League cùng hàng trăm viện nghiên cứu hàng đầu.', 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?q=80&w=1000&auto=format&fit=crop', 'https://images.unsplash.com/photo-1485738422979-f5c462d49f74?q=80&w=1200&auto=format&fit=crop', true, 1, 'Hệ thống bao gồm Đại học 4 năm, Cao đẳng cộng đồng 2 năm (2+2) và các trường sau đại học.', ARRAY['THPT Nội trú', 'Cao đẳng cộng đồng', 'Cử nhân', 'Thạc sĩ / MBA'], ARRAY['Khoa học máy tính & AI', 'Quản trị kinh doanh & Tài chính', 'Kỹ thuật cơ khí'], '$25,000 - $65,000 USD / năm', '$12,000 - $18,000 USD / năm', 'Visa F-1 sinh viên quốc tế: Mẫu I-20, phí SEVIS I-901, đơn DS-160 và phỏng vấn trực tiếp.', 'https://vn.usembassy.gov/visas/nonimmigrant-visas/'),
('11111111-1111-1111-1111-111111111102', 'Du học Úc', 'uc', 'AU', 'Chất lượng giáo dục chuẩn mực thuộc Nhóm G8, môi trường sống an toàn và chính sách visa việc làm sau tốt nghiệp hấp dẫn.', 'Úc là quốc gia có 7 thành phố nằm trong Top những điểm đến du học lý tưởng nhất thế giới. Các trường đại học thuộc Liên minh G8 (Group of Eight) luôn giữ thứ hạng cao trên các bảng xếp hạng thế giới.', 'https://images.unsplash.com/photo-1506973035872-a4ec16b8e8d9?q=80&w=1000&auto=format&fit=crop', 'https://images.unsplash.com/photo-1523482580672-f109ba8cb9be?q=80&w=1200&auto=format&fit=crop', true, 2, 'Khung bằng cấp chuẩn quốc gia AQF gồm: Cao đẳng nghề (TAFE), Cử nhân 3 năm, Thạc sĩ 1.5 - 2 năm.', ARRAY['THPT', 'Dự bị đại học / TAFE', 'Cử nhân', 'Thạc sĩ'], ARRAY['Công nghệ thông tin & Khoa học dữ liệu', 'Kế toán & Phân tích tài chính', 'Điều dưỡng'], '$28,000 - $48,000 AUD / năm', '$22,000 - $28,000 AUD / năm', 'Visa 500 (Student Visa): Yêu cầu CoE, bảo hiểm OSHC, chứng minh tài chính và thư Genuine Student (GS).', 'https://immi.homeaffairs.gov.au/visas/getting-a-visa/visa-listing/student-500'),
('11111111-1111-1111-1111-111111111103', 'Du học Anh', 'anh', 'UK', 'Cái nôi học thuật lâu đời với thời gian đào tạo tối ưu: Cử nhân 3 năm, Thạc sĩ chỉ 1 năm, tiết kiệm chi phí tối đa.', 'Vương quốc Anh tự hào sở hữu nhiều viện đại học cổ kính và danh tiếng như Oxford, Cambridge, Imperial College London cùng nhóm Russell Group.', 'https://images.unsplash.com/photo-1513635269975-59663e0ac1ad?q=80&w=1000&auto=format&fit=crop', 'https://images.unsplash.com/photo-1520986606214-8b456906c813?q=80&w=1200&auto=format&fit=crop', true, 3, 'Chương trình A-Level / Foundation (1 năm), Cử nhân (3 năm), Thạc sĩ (1 năm toàn thời gian).', ARRAY['A-Level / Foundation', 'Cử nhân (3 năm)', 'Thạc sĩ (1 năm)'], ARRAY['Tài chính - Ngân hàng', 'Luật quốc tế', 'Khoa học máy tính'], '£16,000 - £35,000 GBP / năm', '£12,000 - £15,000 GBP / năm', 'Student Visa: CAS từ trường được cấp phép, chứng minh tài chính tối thiểu 28 ngày, IELTS for UKVI.', 'https://www.gov.uk/student-visa'),
('11111111-1111-1111-1111-111111111104', 'Du học Canada', 'canada', 'CA', 'Quốc gia đáng sống nhất với môi trường an toàn, chính sách định cư rộng mở và visa làm việc sau tốt nghiệp PGWP 3 năm.', 'Canada nổi tiếng với sự mến khách, xã hội văn minh và chất lượng đào tạo được kiểm định nghiêm ngặt bởi các tỉnh bang.', 'https://images.unsplash.com/photo-1517935703635-27190775268c?q=80&w=1000&auto=format&fit=crop', 'https://images.unsplash.com/photo-1503614472-8c93d56e92ce?q=80&w=1200&auto=format&fit=crop', true, 4, 'Bao gồm THPT, Cao đẳng nghề (1-3 năm), Đại học Cử nhân (4 năm) và Sau đại học.', ARRAY['THPT', 'Cao đẳng nghề', 'Cử nhân', 'Thạc sĩ'], ARRAY['Kỹ thuật phần mềm', 'Quản trị logistics', 'Kế toán'], '$18,000 - $38,000 CAD / năm', '$15,000 - $20,000 CAD / năm', 'Study Permit: Yêu cầu thư chấp thuận PAL, thư mời LOA, chứng minh tài chính theo quy định IRCC.', 'https://www.canada.ca/en/immigration-refugees-citizenship/services/study-canada.html')
INSERT INTO public.services (name, slug, short_description, content, image_url, features, is_published, sort_order)
VALUES
('Định hướng Quốc gia, Trường & Ngành học', 'dinh-huong-quoc-gia-truong-nganh', 'Phân tích năng lực học thuật, sở thích cá nhân và ngân sách gia đình để xây dựng lộ trình du học phù hợp nhất.', 'Việc lựa chọn đúng ngành và đúng trường là bước đi quyết định sự thành bại của toàn bộ chuyến du học.', 'https://images.unsplash.com/photo-1522202176988-66273c2fd55f?q=80&w=800&auto=format&fit=crop', ARRAY['Tư vấn 1-1 chuyên sâu', 'Phân tích dữ liệu học phí minh bạch', 'Hơn 500+ trường đối tác'], true, 1),
('Hỗ trợ Chuẩn bị Hồ sơ Tuyển sinh', 'chuan-bi-ho-so-tuyen-sinh', 'Tối ưu hóa bảng điểm, dịch thuật công chứng chuẩn xác và hướng dẫn viết bài luận cá nhân (Personal Statement) ấn tượng.', 'Một bộ hồ sơ xin học ấn tượng không chỉ nằm ở điểm số cao mà còn nằm ở câu chuyện riêng biệt của bạn.', 'https://images.unsplash.com/photo-1434030216411-0b793f4b4173?q=80&w=800&auto=format&fit=crop', ARRAY['Hiệu đính bài luận chuyên nghiệp', 'Dịch thuật công chứng nhanh chóng'], true, 2),
('Hướng dẫn & Luyện Phỏng vấn Visa', 'huong-dan-ho-so-visa', 'Chuẩn bị hồ sơ chứng minh tài chính chuẩn chỉ và tổ chức các buổi phỏng vấn giả định 1-1 với kịch bản thực tế.', 'Quy trình xin visa du học đòi hỏi sự chính xác tuyệt đối và tính minh bạch.', 'https://images.unsplash.com/photo-1554224155-8d04cb21cd6c?q=80&w=800&auto=format&fit=crop', ARRAY['Cập nhật luật visa du học mới nhất', 'Luyện phỏng vấn giả định 1-1'], true, 3),
('Chiến lược Săn Học bổng Giá trị Cao', 'chien-luoc-san-hoc-bong', 'Tìm kiếm học bổng 30% - 100% học phí, hướng dẫn viết luận học bổng và luyện phỏng vấn vòng chung kết.', 'Học bổng giúp giảm bớt gánh nặng tài chính đáng kể cho gia đình.', 'https://images.unsplash.com/photo-1523240795612-9a054b0db644?q=80&w=800&auto=format&fit=crop', ARRAY['Bộ sưu tập học bổng độc quyền', 'Chiến lược nộp đơn sớm'], true, 4)
